// comment). Same live-comment guard + idempotency as InsertCommentView.
// §42: gated_types skips comments on feature-flag-unreachable parents.
func (q *Queries) InsertCommentViews(ctx context.Context, arg InsertCommentViewsParams) error {
	_, err := q.db.Exec(ctx, insertCommentViews, arg.UserID, arg.CommentIds, arg.GatedTypes)
	return err
}

